const body = $json.body && typeof $json.body === 'object' ? $json.body : $json;
const defaultSources = ['arbeitnow', 'jobicy', 'remoteok', 'himalayas'];
const asStrings = (value, fallback) => Array.isArray(value) ? value.filter(item => typeof item === 'string' && item.trim()) : fallback;
const boundedInteger = (value, fallback, min, max) => Number.isInteger(value) ? Math.max(min, Math.min(max, value)) : fallback;
const actorInput = {
  sources: asStrings(body.sources, defaultSources),
  keywords: asStrings(body.keywords, ['software']),
  locations: asStrings(body.locations, []),
  maxAgeDays: boundedInteger(body.maxAgeDays, 7, 0, 365),
  limit: boundedInteger(body.limit, 20, 1, 100),
  includeDescription: body.includeDescription === true
};
return [{ json: { actorInput } }];

const entries = $input.all();
const first = entries.length === 1 ? entries[0].json : null;
let jobs;
if (Array.isArray(first)) {
  jobs = first;
} else if (first && Array.isArray(first.body)) {
  jobs = first.body;
} else if (first && Array.isArray(first.data)) {
  jobs = first.data;
} else if (first && Array.isArray(first.items)) {
  jobs = first.items;
} else {
  jobs = entries.map(entry => entry.json);
}
jobs = jobs.filter(job => job && typeof job === 'object' && job.jobTitle);
const date = new Date().toISOString().slice(0, 10);
const lines = jobs.map((job, index) => {
  const location = Array.isArray(job.locations) && job.locations.length ? ` | ${job.locations.join(', ')}` : '';
  const company = job.company || 'Unknown company';
  return `${index + 1}. ${job.jobTitle} - ${company}${location}\n   ${job.url || job.applyUrl || ''}`;
});
return [{
  json: {
    date,
    count: jobs.length,
    digestText: [`Remote jobs for ${date}`, `Found ${jobs.length} matching listings`, ...lines].join('\n'),
    jobs
  }
}];
